Q: How can I get rid of this ASP.NET boilerplate? A: <p>Controllers should not contain business logic such as database access, etc. You need te create another service class like WorkspaceService and all needed logic into it. For your example it would look something like this:</p>
<pre class="lang-cs prettyprint-override"><code>
public sealed class WorkspaceService: IWorkspaceService
{
    private sealed class AppointmentResultDto
    {
        public bool WorkspaceFounded {get; set;}
        public bool UserFounded {get; set;}
        public AppointmentDto AppointmentModel {get; set;}
    }

    //private fields

    public WorkspaceService()
    {
        //di logic
    }

    public async Task&lt;AppointmentResultDto&gt; CreateAppointment(Guid workspaceId, AppointmentCreateModel model, string userName, CancellationToken cancellation)
    {
        var appointmentResult = await CheckWorkspace(workspaceId, userName, cancellation);

        var appointment = new Appointment
        {
            WorkspaceId = workspaceId,
            ContactName = model.ContactName,
            OriginalName = model.ContactName,
            AppointmentTime = model.AppointmentTime,
            Source = AppointmentSource.Dashboard,
            CreatedAt = DateTime.UtcNow,
        };

        db.Appointments.Add(appointment);

        await db.SaveChangesAsync(cancellation);

        appointmentResult.AppointmentModel = appointment;

        return appointmentResult;
    }

    private async Task&lt;AppointmentResultDto&gt; CheckWorkspace(Guid workspaceId, string userName, CancellationToken cancellation)
    {
        var result = new AppointmentResultDto();

        var workspace = await db.Workspaces
            .Include(w =&gt; w.Members)
            .ThenInclude(m =&gt; m.User)
            .FirstOrDefaultAsync(w =&gt; w.Id == workspaceId, cancellation);

        result.WorkspaceFounded = workspace is null;

        if (!result.WorkSpaceFounded)
        {
            return result;
        }

        if (!workspace.Members.Any(m =&gt; m.User.Email == userName))
            result.UserFounded = false;

        return result;
    }
}  
</code></pre>
<p>Now the business logic is in its own service method, and the repeating code with the workspace check is moved to a separate private function. This approach is scalable - additional logic is placed in other methods. Repeated code must be put into functions. It is also important not to forget about using CancellationToken.</p>
<p>And your controller will now look like this:</p>
<pre><code>private readonly IWorkspaceService _workspaceService;

public AppointmentController(IWorkspaceService workspaceService)
{
    _workspaceService = workspaceService;
}

[HttpPost(&quot;{workspaceId}&quot;)]
[ProducesResponseType(StatusCodes.Status200OK)]
[ProducesResponseType(StatusCodes.Status403Forbidden)]
[ProducesResponseType(StatusCodes.Status404NotFound)]
public async Task&lt;IActionResult&gt; Create(Guid workspaceId, [FromBody] AppointmentCreateModel model, CancellationToken cancellation)
{
  var appointmentResult = await _workspaceService.CreateAppointment(workSpaceId, model, User.Identity!.Name, cancellation);

  if (!appointmentResult.WorkspaceFounded)
    return NotFound();

  if (!appointmentResult.UserFounded)
    return Forbid();

  return Ok(appointmentResult.AppointmentModel);
}
</code></pre>
<p>Key points:<br />
1. Business logic is not contained in the controller - this is an antipattern.<br />
2. The solution becomes scalable.<br />
3. Don't forget to write an interface for the service and register it in DI.<br />
4. Don’t forget to use CancellationToken, which is passed from the endpoint to services and then as a parameter to various asynchronous functions. This is a standard mechanism for interrupting execution when the result is no longer needed.</p>
